<script setup lang="ts">
import {reactive} from 'vue'
import {useTemplatePage} from '../hooks/useTemplatePage'
const props=defineProps<{level:number}>(),vm=reactive(useTemplatePage(props.level))
</script>
<template><a-card :title="(level===1?'公司':'项目')+'任务模板'">
 <template #extra><a-space><a-button @click="vm.load">刷新</a-button><a-button v-if="vm.can('quality-configuration','save')" type="primary" @click="vm.start()">新建模板</a-button></a-space></template><a-alert v-if="vm.error" type="error" :message="vm.error" show-icon />
 <a-select v-if="level===2" v-model:value="vm.projectId" :options="vm.projects.map(p=>({value:p.id,label:p.name}))" style="width:240px;margin-bottom:16px" placeholder="业务项目" />
 <a-table :data-source="vm.rows" :loading="vm.loading" row-key="id"><a-table-column title="模板名称" data-index="name" /><a-table-column title="类型" key="type"><template #default="{record}">{{record.data.templateType===2?'配置模板库':'任务模板'}}</template></a-table-column><a-table-column title="总分" key="score"><template #default="{record}">{{record.data.totalScore}}</template></a-table-column><a-table-column title="状态" key="status"><template #default="{record}">{{record.status?'启用':'禁用'}}</template></a-table-column><a-table-column title="操作" key="actions"><template #default="{record}"><a-space><a-button type="link" @click="vm.start(record,false,true)">查看</a-button><template v-if="vm.can('quality-configuration','save')"><a-button type="link" @click="vm.start(record)">编辑</a-button><a-button type="link" @click="vm.start(record,true)">从模板创建</a-button></template><a-popconfirm v-if="vm.can('quality-configuration','delete')" title="删除此模板？" @confirm="vm.remove(record)"><a-button danger type="link">删除</a-button></a-popconfirm></a-space></template></a-table-column></a-table>
 <a-drawer v-model:open="vm.open" :title="vm.viewOnly?'模板详情':vm.form.id?'编辑模板':'新建模板'" width="880"><a-alert v-if="vm.error" type="error" :message="vm.error" show-icon /><a-form layout="vertical" :model="vm.form" :disabled="vm.viewOnly" @finish="vm.save">
 <a-form-item label="模板名称" name="name" :rules="[{required:true,message:'请输入模板名称'}]"><a-input v-model:value="vm.form.name" :maxlength="128" /></a-form-item><a-form-item label="模板类型"><a-radio-group v-model:value="vm.form.data.templateType"><a-radio :value="1">任务模板</a-radio><a-radio :value="2">配置模板库</a-radio></a-radio-group></a-form-item><a-form-item label="任务描述"><a-textarea v-model:value="vm.form.data.taskDescription" /></a-form-item>
 <a-form-item label="检查项"><a-select :value="vm.selected" mode="multiple" :options="vm.configs.map(c=>({value:c.id,label:[c.data.subjectParentName,c.data.parentName,c.name].filter(Boolean).join(' / ')}))" @change="(v:unknown)=>vm.select(v as string[])" show-search option-filter-prop="label" /></a-form-item>
 <a-table :data-source="vm.form.data.configItems" :pagination="false" row-key="configId" size="small"><a-table-column title="检查项" key="name"><template #default="{record}">{{vm.configName(record.configId)}}</template></a-table-column><a-table-column title="分值" key="score"><template #default="{record}"><a-input-number v-model:value="record.score" :precision="0" :min="0" :max="100" :disabled="vm.viewOnly" /></template></a-table-column><a-table-column title="扣分标准" key="deduct"><template #default="{record}"><a-input v-model:value="record.deductionStandard" :disabled="vm.viewOnly" /></template></a-table-column></a-table>
 <a-divider>总分 {{vm.total}}</a-divider><template v-if="level===1"><h3>条线权重（合计 {{vm.weightTotal}}%）</h3><a-form-item v-for="weight in vm.form.data.lineWeights" :key="weight.subjectParentId" :label="weight.subjectParentName||weight.subjectParentId"><a-input-number v-model:value="weight.weight" :min="0" :max="100" addon-after="%" /></a-form-item></template>
 <a-form-item label="状态"><a-switch :checked="vm.form.status===1" @change="(v:unknown)=>vm.form.status=v?1:0" /></a-form-item><a-button v-if="!vm.viewOnly" type="primary" html-type="submit" :loading="vm.saving">保存模板</a-button></a-form></a-drawer>
 </a-card></template>
